    def open_page(self):
        dialog = Ui_Dialog_show_data() 
        dialog.label_temp_avg.setText(f"")
        dialog.label_temp_max.setText(f"")
        dialog.label_temp_min.setText(f"")
 
        dialog.label_city.setText(self.city)
        min_temp = (self.data['main']['temp_min'])
        max_temp = (self.data['main']['temp_max'])
        temp_avg = ((min_temp)+(max_temp))/2
        temp = (self.data['main']['temp'])
        sea_level = (self.data['main']['sea_level']) #sea
        dialog.label_temp_avg.setText(f"{(round(temp_avg , 2))}")
        dialog.label_temp_max.setText(f"{(round(max_temp , 2))}")
        dialog.label_temp_min.setText(f"{(round(min_temp , 2))}")
        dialog.label_temp.setText(f"{(round(temp , 2))}")
        dialog.label_sea_level.setText(f"{sea_level}")
        dialog.label_country.setText(f"{ self.data['sys']['country']}")
        dialog.label_cloud.setText(f"{(self.data['weather'][0]['description'])}")
        
        dialog.label_weather.setText(f"{self.data['weather'][0]['main']}")        
        dialog.setupUi()
        
        dialog.exec_()

    

    
